#include <stdio.h>
int main() {
int arr[ ] = {1, 2, 3, 4, 5, 6};
int i;
int key = 5;
int size = 6;
for (i = 0; i < size; i++) {
if (arr[i] == key) {
printf("Element found at position: %d", i);
break;
}
}
return 0;
}
